   if(!next.steps.length){if(next.finished){session.status='completed';session.finalReply=next.reply;session.phase='已核对实际结果';await changed();return session;}session.status='waiting';session.reason='仍需进一步处理，点击继续或补充要求';await changed();return session;}
   const ids=new Set(session.steps.map(s=>s.id));for(const step of next.steps){if(ids.has(step.id))throw new Error('本轮动作编号重复，已保留所有完成结果');ids.add(step.id);}
