function asLocate(r){if(!r)return;asPause();if(r.fileId)return act('reader.open',{fileId:r.fileId});if(r.runId)return openPan('collaboration',r.runId);if(r.linkId)return act('link.open',{linkId:r.linkId});if(r.projectId&&P(r.projectId)){const p=P(r.projectId);state.activeBoard=p.boardId;state.room=null;state.sel=p.id;fit([p]);renderAll();return}if(r.boardId)act('board.switch',{boardId:r.boardId})}
function asExport(){AS.recordOpen=!AS.recordOpen;renderGuide();if(AS.recordOpen){const el=$('#gl');el.scrollTop=el.scrollHeight}}
const asGuideDecorateBase=renderGuide;renderGuide=function(){asGuideDecorateBase();const s=asSession();for(const dialog of [skillbook,modelConnect]){dialog.querySelector('.as-modal-status')?.remove();if(dialog.open&&s&&(AS.ac||s.status==='waiting'))dialog.insertAdjacentHTML('beforeend',`<div class="as-modal-status"><span>助手：${esc(s.steps[s.cursor]?.label||'正在处理')}</span><button data-as-pause>暂停助手</button><button data-as-return>返回助手</button></div>`)}};
for(const name of ['assistant.bind','assistant.bindGroup','assistant.start','assistant.read','assistant.refine','assistant.library','auth.request'])ACT[name]=a=>{const s={id:'as'+uid(),boardId:state.activeBoard,request:CAT.find(c=>c[0]===name)[1],steps:[{id:'s1',name,label:CAT.find(c=>c[0]===name)[1],args:a,status:'pending',effect:['assistant.start','assistant.refine'].includes(name)?'model':name==='auth.request'?'authorization':'local'}],cursor:0,status:'ready',createdAt:Date.now()};state.assistantSessions.push(s);AS.current=s.id;$('#guide').classList.add('o');void asExecute(s);return'已交给内置助手，进度在助手中显示'};
document.addEventListener('input',e=>{if(e.target.id==='as-input')AS.draft=e.target.value});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-as-history')){if(AS.ac)return;AS.current=e.target.value;AS.recordOpen=false;renderGuide();return}if(e.target.hasAttribute('data-as-binding')){const p=AS.profiles.find(p=>p.id===e.target.value);state.prefs.assistantBinding=p?{connectionId:p.id,model:p.defaultModel}:null;save()}});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.asTab){AS.eduTab=t.dataset.asTab;renderGuide();return;}if(t.hasAttribute('data-as-new')){if(AS.ac)return hint('助手正在执行中，请先暂停');AS.current=null;AS.draft='';AS.localReply='';renderGuide();const inp=$('#as-input');if(inp){inp.value='';inp.focus()}return;}if(t.hasAttribute('data-as-size')||t.closest('[data-as-size]')){const guide=$('#guide');guide.classList.toggle('as-expanded');try{localStorage.setItem('relay_guide_expanded',guide.classList.contains('as-expanded')?'1':'0')}catch{}return;}if(t.dataset.asRoom){const pid=t.dataset.asRoom;if(P(pid)){act('room.enter',{projectId:pid});if(window.innerWidth<1100)$('#guide').classList.remove('o');renderTop();}return;}if(t.hasAttribute('data-as-switch-formal')){act('board.create',{name:'正式创作空间'});const draft=AS.draft||asSession()?.request||'';AS.current=null;AS.draft=draft;AS.localReply='已为你新建并切换到全新正式画板。现在可以随时发送需求，助手将直接为你操作软件。';renderGuide();const inp=$('#as-input');if(inp){inp.value=draft;inp.focus();}return;}if(t.dataset.asPrompt){AS.draft=t.dataset.asPrompt;const inp=$('#as-input');if(inp){inp.value=AS.draft;inp.focus();inp.selectionStart=inp.value.length;inp.selectionEnd=inp.value.length;}return;}if(t.hasAttribute('data-as-send')){const text=$('#as-input').value.trim();if(text){const s=asSession();if(s?.operator&&['waiting','paused','failed'].includes(s.status))void asSteer(text);else void asAsk(text)}}else if(t.hasAttribute('data-as-steer')){const text=$('#as-input').value.trim();if(text)void asSteer(text);else hint('先写下新的要求')}else if(t.hasAttribute('data-as-pause'))asPause();else if(t.hasAttribute('data-as-continue')){const s=asSession();if(s?.operator||s?.steps.length)void asExecute(s,true);else if(s)void asAsk(s.request)}else if(t.hasAttribute('data-as-all')){AS.showAll=!AS.showAll;renderGuide()}else if(t.hasAttribute('data-as-locate'))asLocate(asSession()?.steps.find(x=>x.id===t.dataset.asLocate)?.result);else if(t.hasAttribute('data-as-return')){asCloseAux();$('#guide').classList.add('o');renderGuide()}else if(t.hasAttribute('data-as-export'))asExport();else if(t.hasAttribute('data-as-undo'))act('undo',{});else if(t.hasAttribute('data-as-results')){asCloseAux();$('#guide').classList.remove('o');act('view.fit',{})}else if(t.hasAttribute('data-as-catalog')){AS.localReply='可控组件：'+CAT.map(c=>c[1]).join('、');renderGuide()}else if(t.hasAttribute('data-as-feature')){if(typeof featureBegin==='function')featureBegin()}else if(t.dataset.close==='guide'){$('#guide').classList.remove('o');renderTop();}},true);

const asRestoreBase=restore;restore=function(str){const journal=state.assistantSessions,course=state.featureTour;asRestoreBase(str);state.assistantSessions=journal;state.featureTour=course;save();renderGuide()};
/* ASSISTANT_END */
